#else
#define debug(...)
#define debugArr(...)
#endif
const int maxn = 1005;
const int maxp = 720; 

int P = 0;
int perms[maxp][7];        
int cand[maxn][maxp];
int cand_size[maxn];
int observed[maxn][7];     
int perm_[maxp];

static void build() {
    array<int,6> a = {1,2,3,4,5,6};
    P = 0;
    do {
        for (int i = 0; i < 6; ++i) perms[P][i+1] = a[i];
        ++P;
    } while (next_permutation(a.begin(), a.end()));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    build(); 

    int T;
    cin >> T;

    for (int tc = 0; tc < T; ++tc) {
        int N;
        if (!(cin >> N)) return 0;
        if (N >= maxn) {

            return 0;
        }

        for (int j = 1; j <= N; ++j) {
            cand_size[j] = P;
            for (int k = 0; k < P; ++k) cand[j][k] = k;
            for (int p = 1; p <= 6; ++p) observed[j][p] = 0;
        }

        bool done = false;
        for (int i = 1; i <= 6 && !done; ++i) {
            done = true;

            for (int j = 1; j <= N; ++j) {
                if (cand_size[j] > 1) {
                    done = false;

                    int q_ = 6 * (j - 1) + i; 
                    cout << "? " << q_ << endl;
                    cout.flush();

                    int reply;
                    if (!(cin >> reply)) return 0;
                    if (reply == -1) return 0;

                    observed[j][i] = reply;

                    int write = 0;
                    for (int t = 0; t < cand_size[j]; ++t) {
                        int idx = cand[j][t];
                        bool ok = true;
                        if (perms[idx][i] != reply) ok = false;
                        else {
                            for (int q = 1; q < i; ++q) {
                                if (observed[j][q] != 0) {
                                    if (perms[idx][q] != observed[j][q]) { ok = false; break; }
                                }
                            }
                        }
                        if (ok) {
                            cand[j][write++] = idx;
                        }
                    }
                    cand_size[j] = write;
                    if (cand_size[j] == 0) {

                    }
                }
            }

            done = true;
            for (int j = 1; j <= N; ++j) if (cand_size[j] > 1) { done = false; break; }
        }

        for (int k = 0; k < P; ++k) perm_[k] = 0;
        for (int j = 1; j <= N; ++j) {
            if (cand_size[j] == 0) continue;
            int pick = cand[j][0];
            perm_[pick] = 1;
        }

        int ansind = -1;
        for (int k = 0; k < P; ++k) if (!perm_[k]) { ansind = k; break; }

        if (ansind == -1) ansind = 0; 

        cout << "!";
        for (int p = 1; p <= 6; ++p) cout << " " << perms[ansind][p];
        cout << endl;
    }
}